const flow = document.createElement('section'); flow.className = 'xcrow-flow'; flow.innerHTML = '<span class="tag">HOW XCROW WORKS</span><h2>Five clear steps. One shared escrow.</h2><div class="flow-grid"><div class="flow-step"><i>🤝</i><b>1. Agree</b><p>Buyer and seller agree to the terms and amount.</p></div><div class="flow-step"><i>🔐</i><b>2. Join</b><p>Both parties join one escrow using its unique code.</p></div><div class="flow-step"><i>💳</i><b>3. Deposit</b><p>Deposit with a saved M-Pesa prompt or USDT TRC20.</p></div><div class="flow-step"><i>📦</i><b>4. Deliver</b><p>Seller delivers goods or services and parties keep in touch.</p></div><div class="flow-step"><i>✅</i><b>5. Settle</b><p>Buyer requests release, or both parties agree to refund.</p></div></div>'; $('.payment-strip').after(flow);
const calculator = document.createElement('section'); calculator.className = 'xcrow-calculator'; calculator.id = 'fee-calculator'; calculator.innerHTML = '<span class="tag">TRY OUR FEE CALCULATOR</span><h2>See your escrow fee before you start.</h2><div class="calculator-box"><input id="public-fee-amount" type="number" min="1" step="0.01" placeholder="Transaction amount"><select id="public-fee-currency"><option value="KES">KES</option><option value="USDT">USDT</option></select><select id="public-fee-payer"><option value="buyer">Buyer pays fee</option><option value="seller">Seller pays fee</option><option value="both">Split fee</option></select><button class="button" id="public-fee-button">Calculate fee</button></div><div class="calc-result" id="public-fee-result">Enter an amount, then calculate your fee.</div>'; flow.after(calculator);
$('#public-fee-button').onclick = async () => { const amount = Number($('#public-fee-amount').value); const result = $('#public-fee-result'); if (!amount) return result.textContent = 'Enter a valid transaction amount.'; try { const fee = await api('/api/fees', { method:'POST', body:JSON.stringify({ amount, currency:$('#public-fee-currency').value, payer:$('#public-fee-payer').value }) }); const currency = $('#public-fee-currency').value; result.innerHTML = `<b>Escrow fee: ${fee.amount.toLocaleString()} ${currency}</b><br>Buyer pays ${fee.buyerTotal.toLocaleString()} ${currency} · Seller receives ${fee.sellerReceives.toLocaleString()} ${currency}.`; } catch (error) { result.textContent = error.message; } };
