const official = document.createElement('section'); official.className = 'official-home'; official.id = 'platform-details'; official.innerHTML = `<div class="official-intro"><div><span class="tag">XCROW PLATFORM</span><h2>One clear place to manage an important agreement.</h2><p>XCROW brings the people, payment status, terms, and transaction record into a single shared escrow room. Start with the amount and fee, invite the other party, then follow the deal from deposit to settlement.</p><button class="button" type="button" data-official-start>Open your XCROW account ↗</button></div><div class="official-stats"><div class="official-stat"><b>70K+</b><span>registered members</span></div><div class="official-stat"><b>1.6M+</b><span>released through completed deals</span></div><div class="official-stat"><b>24/7</b><span>human support availability</span></div><div class="official-stat"><b>2</b><span>clearly defined payment methods</span></div></div></div><div class="feature-heading"><span class="tag">PLATFORM FEATURES</span><h3>Built for the full escrow journey.</h3><p>Everything below is available in the XCROW flow or explains how the platform keeps each deal organised.</p></div><div class="official-feature-grid">${officialFeatures.map(([icon,title,copy]) => `<article class="official-feature"><i>${icon}</i><h4>${title}</h4><p>${copy}</p></article>`).join('')}</div><div class="official-bottom"><article class="official-policy"><span class="tag" style="color:#8fd3ff">XCROW PROMISE</span><h3>Clear actions. Visible status.</h3><p>Every party should know the current stage before taking the next step. XCROW is designed to make the deal record easier to follow.</p><ul><li>Only the selected payment method is shown for each deal.</li><li>Payment status is visible to deal participants.</li><li>Completed deals close and remain in account history.</li><li>Appeals route the escrow back to support review.</li></ul></article><article class="official-faq"><span class="tag">COMMON QUESTIONS</span><h3>Before you begin</h3><details><summary>Which payments does XCROW accept?</summary><p>XCROW escrow deals are set up in Kenyan Shilling (KES) or USDT on the TRC20 network. Do not send other tokens or use another USDT network.</p></details><details><summary>Can I invite the other party after creating a deal?</summary><p>Yes. Share the five-letter escrow code so the buyer or seller can join the same deal room.</p></details><details><summary>What happens if an escrow is not used?</summary><p>Setup sessions without a deposit automatically close after one hour. Create a new escrow when you are ready to continue.</p></details><details><summary>How do I get support?</summary><p>You can add XCROW Support from an active escrow, use the live support area, or email xcrowsupport@gmail.com.</p></details></article></div>`; global.after(official); official.querySelector('[data-official-start]').onclick = () => $('#signup').showModal();
