async function api(path, options = {}) { let response; try { response = await fetch(path, { ...options, headers: { 'Content-Type': 'application/json', ...(state.token ? { Authorization: `Bearer ${state.token}` } : {}), ...options.headers } }); } catch { throw new Error('XCROW could not reach the service. Check your connection and retry.'); } const data = response.headers.get('content-type')?.includes('application/json') ? await response.json().catch(() => null) : null; if (!response.ok) throw new Error(data?.error || 'XCROW could not complete that request. Please retry.'); return data; }
function notify(message) { const toast = document.createElement('div'); toast.className = 'toast-live'; toast.textContent = message; Object.assign(toast.style, { position:'fixed', right:'20px', top:'20px', background:'#12213a', color:'#fff', padding:'12px 15px', borderRadius:'7px', zIndex:99, fontSize:'13px', maxWidth:'min(360px,calc(100vw - 40px))' }); document.body.append(toast); setTimeout(() => toast.remove(), 3200); }
function saveAuth(result) { state.token = result.token; state.user = result.user; localStorage.setItem('xcrow_token', state.token); localStorage.setItem('xcrow_user', JSON.stringify(state.user)); openDashboard(true).then(() => { if (location.hash === '#admin') window.showAdmin?.(); }).catch(() => { notify('Your account was saved, but XCROW is still reconnecting. Please refresh in a few seconds.'); }); }
function logout() { localStorage.removeItem('xcrow_token'); localStorage.removeItem('xcrow_user'); location.assign('/'); }
function message(form, value, good = false) { const el = form.querySelector('.message'); el.textContent = value; el.style.color = good ? '#15803d' : '#b91c1c'; }

