document.querySelectorAll('.auth-form').forEach(form => form.onsubmit = async event => { event.preventDefault(); try { message(form, 'Signing you in…', true); const adminLogin = location.hash === '#admin' && form.closest('dialog')?.id === 'login'; saveAuth(await api(adminLogin ? '/api/auth/admin-login' : `/api/auth/${form.closest('dialog').id}`, { method:'POST', body:JSON.stringify(Object.fromEntries(new FormData(form))) })); form.closest('dialog').close(); } catch (error) { message(form, error.message); } });
function b64urlBytes(value) { const padded = String(value).replace(/-/g, '+').replace(/_/g, '/') + '==='.slice((String(value).length + 3) % 4); const binary = atob(padded); return Uint8Array.from(binary, char => char.charCodeAt(0)); }
function bytesB64url(value) { const bytes = new Uint8Array(value); let binary = ''; bytes.forEach(byte => { binary += String.fromCharCode(byte); }); return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/g, ''); }
function passkeyOptions(options) { const publicKey = { ...options, challenge: b64urlBytes(options.challenge) }; if (options.user?.id) publicKey.user = { ...options.user, id: b64urlBytes(options.user.id) }; ['excludeCredentials', 'allowCredentials'].forEach(key => { if (options[key]) publicKey[key] = options[key].map(item => ({ ...item, id: b64urlBytes(item.id) })); }); return publicKey; }
function passkeyCredential(credential) { const response = credential.response; const data = { clientDataJSON: bytesB64url(response.clientDataJSON) }; if (response.attestationObject) { data.attestationObject = bytesB64url(response.attestationObject); data.transports = response.getTransports?.() || []; } else { data.authenticatorData = bytesB64url(response.authenticatorData); data.signature = bytesB64url(response.signature); data.userHandle = response.userHandle ? bytesB64url(response.userHandle) : undefined; } return { id: credential.id, rawId: bytesB64url(credential.rawId), type: credential.type, response: data, clientExtensionResults: credential.getClientExtensionResults?.() || {} }; }
async function setupPasskey() { if (!window.PublicKeyCredential || !navigator.credentials?.create) throw new Error('Passkeys are not supported by this browser or device.'); const options = await api('/api/auth/passkey/register/options', { method:'POST' }); const credential = await navigator.credentials.create({ publicKey: passkeyOptions(options) }); const result = await api('/api/auth/passkey/register/verify', { method:'POST', body:JSON.stringify({ credential: passkeyCredential(credential) }) }); return result.message; }
async function loginWithPasskey(form) { if (!window.PublicKeyCredential || !navigator.credentials?.get) throw new Error('Passkeys are not supported by this browser or device.'); const email = String(new FormData(form).get('email') || '').trim(); if (!email) throw new Error('Enter your email address first.'); const options = await api('/api/auth/passkey/login/options', { method:'POST', body:JSON.stringify({ email }) }); const credential = await navigator.credentials.get({ publicKey: passkeyOptions(options) }); return api('/api/auth/passkey/login/verify', { method:'POST', body:JSON.stringify({ email, credential: passkeyCredential(credential) }) }); }
$('#passkey-login')?.addEventListener('click', async event => { const button = event.currentTarget; const form = button.closest('form'); try { button.disabled = true; button.textContent = 'Waiting for your device…'; message(form, 'Confirm with your fingerprint, face recognition, or device lock.', true); const result = await loginWithPasskey(form); saveAuth(result); form.closest('dialog').close(); } catch (error) { message(form, error.name === 'NotAllowedError' ? 'Passkey sign-in was cancelled or not approved.' : error.message); } finally { button.disabled = false; button.textContent = '🔐 Sign in with passkey'; } });
let googleSignInReady;
async function loadGoogleSignIn() { const config = await api('/api/auth/google/config'); if (!config.clientId) throw new Error('Google sign-in is not configured yet.'); if (!googleSignInReady) googleSignInReady = new Promise((resolve, reject) => { if (window.google?.accounts?.id) return resolve(); const script = document.createElement('script'); script.src = 'https://accounts.google.com/gsi/client'; script.async = true; script.onload = resolve; script.onerror = () => reject(new Error('Google sign-in could not be loaded.')); document.head.append(script); }); await googleSignInReady; return config.clientId; }
$('#google-login')?.addEventListener('click', async event => { const button = event.currentTarget; const form = button.closest('form'); try { button.disabled = true; button.textContent = 'Opening Google…'; const clientId = await loadGoogleSignIn(); window.google.accounts.id.initialize({ client_id: clientId, callback: async response => { try { message(form, 'Verifying your Google account…', true); saveAuth(await api('/api/auth/google', { method:'POST', body:JSON.stringify({ credential: response.credential }) })); form.closest('dialog').close(); } catch (error) { message(form, error.message); } finally { button.disabled = false; button.innerHTML = '<span>G</span>Continue with Google'; } }, auto_select: false, cancel_on_tap_outside: true }); window.google.accounts.id.prompt(notification => { if (notification.isNotDisplayed?.() || notification.isSkippedMoment?.()) { button.disabled = false; button.innerHTML = '<span>G</span>Continue with Google'; message(form, 'Choose a Google account in the prompt, or check that browser pop-ups are allowed.'); } }); } catch (error) { button.disabled = false; button.innerHTML = '<span>G</span>Continue with Google'; message(form, error.message); } });
