async function loadDeals() { state.deals = await api('/api/deals'); $('#history-view h2').textContent = `Welcome, ${state.user.name}`; $('#deals').innerHTML = state.deals.length ? state.deals.map(deal => `<button class="deal-row" data-id="${deal._id}"><div><h3>${safe(deal.title)}</h3><p>Escrow code: <b>${safe(deal.code)}</b><br><small>Created: ${safe(escrowDate(deal.createdAt))}</small></p></div><div><small>Amount</small><br><strong>${Number(deal.amount).toLocaleString()} ${deal.currency}</strong></div><div><span class="status ${statusTone(deal)}">${safe(statusLabel(deal))}</span></div><small>Open →</small></button>`).join('') : '<div class="empty">No escrows yet. Create one or join an existing escrow with its five-letter code.</div>'; document.querySelectorAll('[data-id]').forEach(button => button.onclick = () => showDeal(state.deals.find(deal => deal._id === button.dataset.id))); }
async function refreshFee() { const amount = Number($('#amount-input').value); if (!amount) return $('#fee-preview').textContent = 'Enter an amount to calculate the escrow fee.'; try { const currency = $('#currency-input').value; const fee = await api('/api/fees', { method:'POST', body:JSON.stringify({ amount, currency, payer:$('#fee-payer-input').value }) }); $('#fee-preview').innerHTML = `<b>Escrow fee: ${fee.amount.toLocaleString()} ${currency}</b><br>Buyer pays: ${fee.buyerTotal.toLocaleString()} ${currency} · Seller receives: ${fee.sellerReceives.toLocaleString()} ${currency}${currency === 'USDT' ? `<br><small>Rate used: 1 USDT = ${fee.rate} KES.</small>` : ''}`; } catch (error) { $('#fee-preview').textContent = error.message; } }
['#amount-input','#currency-input','#fee-payer-input'].forEach(selector => $(selector).addEventListener(selector === '#amount-input' ? 'input' : 'change', refreshFee));
$('#create-deal').onsubmit = async event => { event.preventDefault(); const form = event.currentTarget; try { const deal = await api('/api/deals', { method:'POST', body:JSON.stringify(Object.fromEntries(new FormData(form))) }); form.reset(); state.deals.unshift(deal); notify(`Escrow ${deal.code} created.`); showDeal(deal); } catch (error) { message(form, error.message); } };

function copy(value, button) { navigator.clipboard.writeText(value).then(() => { const original = button.textContent; button.textContent = 'Copied'; setTimeout(() => button.textContent = original, 1200); }); }
function myRole(deal) { return deal.parties.find(p => String(p.user) === String(state.user.id))?.role; }
function statusLabel(deal) { if (deal.status !== 'Closed') return deal.status; if (deal.finalStatus === 'Released') return 'Released · Escrow closed'; if (deal.finalStatus === 'Refunded') return 'Refunded · Escrow closed'; if (deal.finalStatus === 'Cancelled') return 'Cancelled · Escrow closed'; return 'Escrow closed'; }
function statusTone(deal) { if (deal.status === 'Funded') return 'funded'; if (deal.status === 'Closed' && deal.finalStatus === 'Released') return 'released'; if (deal.status === 'Closed' && deal.finalStatus === 'Refunded') return 'refunded'; return ''; }
function closedMessage(deal) { if (deal.finalStatus === 'Released') return 'Escrow closed after release.'; if (deal.finalStatus === 'Refunded') return 'Escrow closed after refund.'; if (deal.finalStatus === 'Cancelled') return 'Escrow cancelled before funding.'; return deal.closeReason || 'Timed out. Please open a new escrow.'; }
async function showDeal(deal) { state.active = deal._id; showView('deal'); const role = myRole(deal); const fee = deal.fee || { amount:0, buyerTotal:deal.amount, sellerReceives:deal.amount }; const otherRoles = ['buyer','seller','third_party'].filter(item => !deal.parties.some(p => p.role === item)); const invite = `${location.origin}${deal.thirdPartyInvite}`; const canStart = deal.status === 'Ready to deposit' && role === deal.depositRole; const payment = deal.payments?.at(-1); const receipt = payment?.status === 'paid' ? `<a class="receipt" data-receipt="${payment._id}">Download confirmed receipt</a>` : ''; const pendingKes = deal.currency === 'KES' && payment?.method === 'KES_STK' && payment.status === 'pending' && role === deal.depositRole; const usdtSummary = `<div class="usdt-payment"><b>USDT · TRC20 deposit 💎</b><p>Amount to deposit: <b>${Number(fee.buyerTotal).toLocaleString()} USDT</b></p><img src="/usdt-trc20-qr.png" alt="TRC20 USDT QR code"><p class="notice">Deposits are automatically credited once paid and confirmed on the TRC20 network. 📡</p><code>THESvopuBtMGHnbok39ZUBh2EkV7m4Kwne</code><button class="copy" id="copy-usdt">Copy TRC20 address</button></div>`; const depositArea = canStart ? deal.currency === 'USDT' ? usdtSummary : `<div class="fee-preview"><b>Deposit summary 💳</b><br>Amount to deposit: ${Number(fee.buyerTotal).toLocaleString()} KES</div><button class="button" id="deposit">Deposit to XCROW 💰</button>` : pendingKes ? `<div class="fee-preview"><b>Deposit summary 💳</b><br>Amount: ${Number(payment.amount).toLocaleString()} KES<br>Prompt sent to your saved M-Pesa number.</div><button class="copy" id="resend">Resend payment prompt 🔁</button>` : payment?.checkoutUrl && role === deal.depositRole && payment.status === 'pending' ? usdtSummary : `<p class="detail-meta">${deal.status === 'Awaiting participants' ? 'Share the escrow code with the buyer or seller so they can join.' : deal.status === 'Ready to deposit' ? `The ${deal.depositRole} can now make the deposit.` : deal.status === 'Funded' ? 'Payment confirmed.' : 'Your deposit is being processed.'}</p>`; $('#deal-view').innerHTML = `<button class="back" data-view="history">← Back to escrows</button><span class="tag">ESCROW CODE · ${safe(deal.code)}</span><div class="deal-detail"><span class="status">${safe(deal.status)}</span><h3>${safe(deal.title)}</h3><p>${safe(deal.description)}</p><div class="detail-meta">Created: ${safe(escrowDate(deal.createdAt))}<br>${Number(deal.amount).toLocaleString()} ${deal.currency} · Your role: ${safe(role)}</div><div class="fee-preview"><b>Fee: ${Number(fee.amount).toLocaleString()} ${deal.currency}</b><br>Buyer pays ${Number(fee.buyerTotal).toLocaleString()} ${deal.currency} · Seller receives ${Number(fee.sellerReceives).toLocaleString()} ${deal.currency}</div><p><b>Participants:</b> ${deal.parties.map(p => `${safe(p.name)} (${safe(p.role)})`).join(' · ')}</p>${depositArea}${otherRoles.includes('third_party') ? `<div class="invite-box"><strong>Third-party invite</strong><p>${safe(invite)}</p><button class="copy" id="copy-invite">Copy invite link</button></div>` : ''}${receipt}<hr><h3>Escrow chat</h3><div id="chat" class="chat"><div class="chat-connecting"><span>🤖</span><b>Automated XCROW Bot is opening the secure room</b><i><em></em><em></em><em></em></i></div></div><form id="chat-form" class="chat-form"><input name="body" maxlength="1500" placeholder="Write a message to everyone in this escrow" required><button class="button">Send</button></form></div>`; $('[data-view="history"]').onclick = () => { showView('history'); loadDeals(); }; $('#copy-invite')?.addEventListener('click', event => copy(invite, event.target)); $('#copy-usdt')?.addEventListener('click', event => copy('THESvopuBtMGHnbok39ZUBh2EkV7m4Kwne', event.target)); $('#deposit')?.addEventListener('click', () => startCheckout(deal)); $('#resend')?.addEventListener('click', () => resendStk(deal)); $('#resume')?.addEventListener('click', () => location.assign(payment.checkoutUrl)); $('[data-receipt]')?.addEventListener('click', () => downloadReceipt(deal, payment)); $('#chat-form').onsubmit = async event => { event.preventDefault(); try { await api(`/api/deals/${deal._id}/messages`, { method:'POST', body:JSON.stringify(Object.fromEntries(new FormData(event.currentTarget))) }); event.currentTarget.reset(); loadMessages(deal._id); } catch (error) { notify(error.message); } }; loadMessages(deal._id); }
function botTyping(show) { const typing = $('#deal-view .bot-typing'); if (typing) typing.hidden = !show; }
async function loadMessages(dealId) { const chat = $('#chat'); try { const entries = await api(`/api/deals/${dealId}/messages`); if (state.active !== dealId || !chat) return; chat.innerHTML = entries.map(item => `<p class="${String(item.sender || '') === String(state.user.id) ? 'mine' : 'incoming'}"><b>${safe(item.senderName)}</b><span>${safe(item.body)}</span><small>${new Date(item.createdAt).toLocaleTimeString([], { hour:'2-digit', minute:'2-digit' })}</small></p>`).join(''); chat.scrollTop = chat.scrollHeight; } catch (error) { if (state.active === dealId) notify('Conversation could not refresh. Please retry.'); } }
