async function openUsdtPayment(deal, checkout) { const info = await api('/api/payment-info'); const chain = checkout.cryptoChain || deal.cryptoChain || 'TRC20'; const isBep20 = chain === 'BEP20'; const address = isBep20 ? info.usdtBep20Address : info.usdtAddress; const label = isBep20 ? 'BEP20 · BNB Smart Chain' : 'TRC20 · TRON'; const dialog = document.createElement('dialog'); dialog.innerHTML = `<div class="modal"><button class="close" type="button">×</button><span class="tag">USDT · ${chain}</span><h2>USDT deposit</h2><div class="usdt-payment"><p class="notice">Send USDT using ${label} only. The secure HashPay checkout confirms the deposit automatically after network verification. 📡</p><img src="${isBep20 ? '/usdt-bep20-qr.png' : '/usdt-trc20-qr.png'}" alt="USDT ${label} payment QR code"><p>Send exactly <b>${Number(deal.fee.buyerTotal).toLocaleString()} USDT</b> to:</p><code>${safe(address)}</code><button class="copy" id="copy-crypto-address" type="button">Copy ${chain} address</button></div><button class="button" id="continue-usdt" type="button">Continue to secure checkout ↗</button></div>`; document.body.append(dialog); dialog.showModal(); dialog.querySelector('.close').onclick = () => dialog.close(); dialog.querySelector('#copy-crypto-address').onclick = event => copy(address, event.target); dialog.querySelector('#continue-usdt').onclick = () => location.assign(checkout.checkoutUrl); }
